    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    active = [any(v != bg for v in row) for row in grid]
    bands = []
    r = 0
    while r < h:
        if not active[r]:
            r += 1
            continue
        start = r
        while r < h and active[r]:
            r += 1
        bands.append((start, r))
    out = [row[:] for row in grid]
    if len(bands) != 2 or (bands[0][1] - bands[0][0]) != (bands[1][1] - bands[1][0]):
        return out

    (a0, a1), (b0, b1) = bands
    n = a1 - a0
    best = None
    # Find the horizontal registration of the repeated bands by foreground
    # overlap. dx maps a column in the first band to column c+dx in the second.
    for dx in range(-4, 5):
        inter = union = 0
        for k in range(n):
            a, b = grid[a0 + k], grid[b0 + k]
            for c, v in enumerate(a):
                q = c + dx
                if 0 <= q < w and v != bg and b[q] != bg:
                    inter += 1
            for c, v in enumerate(a):
                q = c + dx
                if not 0 <= q < w:
                    continue
                if v != bg or b[q] != bg:
                    union += 1
        score = (inter / union if union else 0, inter, -abs(dx), -dx)
        if best is None or score > best[0]:
            best = (score, dx)
    dx = best[1]

    # With a rightward offset, mark the second (shifted) copy; otherwise mark
    # the first. This also handles a zero-offset repeated pattern.
    target_second = dx > 0
    for k in range(n):
        ra, rb = a0 + k, b0 + k
        if target_second:
            target, ref, shift = rb, ra, dx
        else:
            target, ref, shift = ra, rb, -dx
        # Ignore the unpaired edge introduced by translation. Start marking
        # only once the aligned rows first disagree, preserving their common prefix.
        valid = [c for c in range(w) if 0 <= c - shift < w]
        first_diff = None
        for c in valid:
            if (grid[target][c] != bg) != (grid[ref][c - shift] != bg):
                first_diff = c
                break
