def transform(grid):
    """Highlight the unmatched right-hand continuation of repeated row bands."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    fg = next((v for v, _ in counts.most_common() if v != bg), None)
    if fg is None:
        return [row[:] for row in grid]

    active = [any(v == fg for v in row) for row in grid]
    groups = []
    for r, present in enumerate(active):
        if not present:
            continue
        if not groups or r > groups[-1][-1] + 1:
            groups.append([r])
        else:
            groups[-1].append(r)
    if len(groups) != 2 or len(groups[0]) != len(groups[1]):
        return [row[:] for row in grid]
    first, second = groups

    # dx maps a foreground cell in the first band at c to second-band c+dx.
    best = None
    for dx in range(-4, 5):
        overlap = union = 0
        for ra, rb in zip(first, second):
            for c in range(w):
                q = c + dx
                if not 0 <= q < w:
                    continue
                x, y = grid[ra][c] == fg, grid[rb][q] == fg
                overlap += int(x and y)
                union += int(x or y)
        score = (overlap / union if union else 0, overlap, -abs(dx), -dx)
        if best is None or score > best[0]:
            best = (score, dx)
    dx = best[1]

    # A positive shift makes the second band the shifted/truncated copy;
    # otherwise the first band is the target. Only mark mismatches to the right
    # of the last shared foreground cell, leaving the common pattern untouched.
    target_second = dx > 0
    out = [row[:] for row in grid]
    for ra, rb in zip(first, second):
        if target_second:
            target_row, source_row = rb, ra
            pairs = [(c + dx, c) for c in range(w) if 0 <= c + dx < w]
        else:
            target_row, source_row = ra, rb
            pairs = [(c, c + dx) for c in range(w) if 0 <= c + dx < w]
        shared = [tc for tc, sc in pairs
                  if grid[target_row][tc] == fg and grid[source_row][sc] == fg]
        if not shared:
            continue
        last_shared = max(shared)
        for tc, sc in pairs:
            if tc > last_shared and (grid[target_row][tc] == fg) != (grid[source_row][sc] == fg):
                out[target_row][tc] = 1
    return out
